TYPE.TEST:


SetFunctionName("MaskScalar(bool)");

MaskScalar maskA(true);
MaskScalar maskB(false);

Validate( maskA.GetBool() && (!maskB.GetBool()) );


#ifdef HOST_TESTING
        SetFunctionName("MaskScalar(uint32_t)");

        uint32_t maskValue = 0x01020304;
        MaskScalar mask(maskValue);

        Validate( mask.ToUInt32() == maskValue );
#endif



SetFunctionName("MaskScalar(const MaskScalar&)");

MaskScalar maskATemp(true);
MaskScalar maskBTemp(false);
MaskScalar maskA(maskATemp);
MaskScalar maskB(maskBTemp);

Validate( maskA.GetBool() && (!maskB.GetBool()) );



SetFunctionName("MaskScalar& operator =(const MaskScalar&)");

MaskScalar maskATemp(true);
MaskScalar maskBTemp(false);
MaskScalar maskA;
MaskScalar maskB;
maskA = maskATemp;
maskB = maskBTemp;

Validate( maskA.GetBool() && (!maskB.GetBool()) );



#ifdef GENERIC_TESTING
        SetFunctionName("MaskScalar(float_test_type)");

        MaskScalar maskA((float_test_type)20.0f);
        MaskScalar maskB((float_test_type)-7.0f);

        Validate( maskA.GetBool() && (!maskB.GetBool()) );
#endif



#ifdef HOST_TESTING
        SetFunctionName("MaskScalar(VectorIntrinsic)");

        MaskScalar maskATemp(true);
        MaskScalar maskBTemp(false);
        MaskScalar maskA(maskATemp.mV);
        MaskScalar maskB(maskBTemp.mV);

        Validate( maskA.GetBool() && (!maskB.GetBool()) );
#endif



SetFunctionName("Not(MaskScalar)");

MaskScalar trueMask(true);
MaskScalar falseMask(false);

Validate( !Not(trueMask).GetBool() && Not(falseMask).GetBool() );



SetFunctionName("And(MaskScalar)");

MaskScalar trueMask(true);
MaskScalar falseMask(false);

Validate( 
    (!And( falseMask, falseMask ).GetBool()) &&
    (!And( falseMask,  trueMask ).GetBool()) &&
    (!And(  trueMask, falseMask ).GetBool()) &&
    ( And(  trueMask,  trueMask ).GetBool())
);



SetFunctionName("Or(MaskScalar)");

MaskScalar trueMask(true);
MaskScalar falseMask(false);

Validate( 
    (!Or( falseMask, falseMask ).GetBool()) &&
    ( Or( falseMask,  trueMask ).GetBool()) &&
    ( Or(  trueMask, falseMask ).GetBool()) &&
    ( Or(  trueMask,  trueMask ).GetBool())
);



SetFunctionName("Xor(MaskScalar)");

MaskScalar trueMask(true);
MaskScalar falseMask(false);

Validate( 
    (!Xor( falseMask, falseMask ).GetBool()) &&
    ( Xor( falseMask,  trueMask ).GetBool()) &&
    ( Xor(  trueMask, falseMask ).GetBool()) &&
    (!Xor(  trueMask,  trueMask ).GetBool())
);



SetFunctionName("CompEqual(MaskScalar)");

MaskScalar trueMask(true);
MaskScalar falseMask(false);

Validate( 
    ( CompEqual( falseMask, falseMask ).GetBool()) &&
    (!CompEqual( falseMask,  trueMask ).GetBool()) &&
    (!CompEqual(  trueMask, falseMask ).GetBool()) &&
    ( CompEqual(  trueMask,  trueMask ).GetBool())
);



SetFunctionName("CompNotEqual(MaskScalar)");

MaskScalar trueMask(true);
MaskScalar falseMask(false);

Validate( 
    (!CompNotEqual( falseMask, falseMask ).GetBool()) &&
    ( CompNotEqual( falseMask,  trueMask ).GetBool()) &&
    ( CompNotEqual(  trueMask, falseMask ).GetBool()) &&
    (!CompNotEqual(  trueMask,  trueMask ).GetBool())
);



SetFunctionName("SetTrue()");

MaskScalar mask;
mask.SetTrue();

Validate( mask.GetBool() );



SetFunctionName("MaskScalar Select(MaskScalar mask, MaskScalar a, MaskScalar b)");
MaskScalar v1(true);
MaskScalar v2(false);

MaskScalar result1 = Select( MaskScalar(true), v1, v2 );
MaskScalar result2 = Select( MaskScalar(false), v1, v2 );
Validate(
    CompEqual(result1, v1).GetBool() &&
    CompEqual(result2, v2).GetBool()
);
